import {
  mkdtemp,
  readFile,
  rm,
  stat,
  writeFile
} from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { runInNewContext } from 'node:vm';
import {
  afterEach,
  beforeEach,
  describe,
  expect,
  it,
  vi
} from 'vitest';

import {
  DEFAULT_OBSIDIAN_PLUGIN_LINE_LIMIT,
  limitLineLength,
  limitMainJsLineLength
} from './obsidian-plugin-line-limit.ts';

const BANNER = '/*\nTHIS IS A GENERATED/BUNDLED FILE BY PARCEL\n*/\n';
const LINE_LIMIT = 100;
const STATEMENT_COUNT = 200;

function evaluate(code: string): Record<string, unknown> {
  const exports: Record<string, unknown> = {};
  runInNewContext(code, { exports });
  return exports;
}

function makePackedBundle(): string {
  const statements = Array.from({ length: STATEMENT_COUNT }, (_, index) => `exports.v${String(index)}="é, ${String(index)};",exports.r${String(index)}=/[,;]/.source`);
  return `${statements.join(';')};/*! @license MIT */exports.t=\`a,b;c\`;function f(){return 1}exports.f=f();`;
}

describe('limitLineLength', () => {
  it('breaks a packed bundle at the line limit without changing what it does', () => {
    const code = makePackedBundle();
    const limited = limitLineLength(code, LINE_LIMIT);

    const lines = limited.split('\n');
    expect(lines.length).toBeGreaterThan(1);
    expect(Math.max(...lines.map((line) => line.length))).toBeLessThan(LINE_LIMIT * 2);
    expect(evaluate(limited)).toEqual(evaluate(code));
  });

  it('changes nothing but the line feeds it adds', () => {
    const code = `${BANNER}${makePackedBundle()}`;
    const limited = limitLineLength(code, LINE_LIMIT);

    expect(limited.length - code.length).toBe(limited.split('\n').length - code.split('\n').length);
    expect(limited.replaceAll('\n', '')).toBe(code.replaceAll('\n', ''));
  });

  it('never breaks inside a string, a template or a regular expression', () => {
    const limited = limitLineLength(makePackedBundle(), LINE_LIMIT);

    expect(limited).toContain('"é, 199;"');
    expect(limited).toContain('/[,;]/');
    expect(limited).toContain('`a,b;c`');
  });

  it('counts a line from the last line feed already in the code', () => {
    const code = `${'a=1,'.repeat(5)}\n${'b=2,'.repeat(10)}b=3;`;

    expect(limitLineLength(code, 30)).toBe(`${'a=1,'.repeat(5)}\n${'b=2,'.repeat(8)}\nb=2,b=2,b=3;`);
  });

  it('does not add a line feed where one already is', () => {
    const code = `${'a=1,'.repeat(10)}a=1;\n${'b=2,'.repeat(5)}`.slice(0, -1);

    expect(limitLineLength(code, 43)).toBe(code);
  });

  it('leaves a bundle with no line over the limit unchanged', () => {
    const code = 'exports.a = 1;\nexports.b = 2;\n';

    expect(limitLineLength(code, LINE_LIMIT)).toBe(code);
  });

  it('leaves a long line with nothing to break at unchanged', () => {
    const code = `exports.a="${'x'.repeat(LINE_LIMIT * 2)}"`;

    expect(limitLineLength(code, LINE_LIMIT)).toBe(code);
  });

  it('leaves a bundle that references a source map unchanged', () => {
    const code = `${makePackedBundle()}\n//# sourceMappingURL=main.js.map`;

    expect(limitLineLength(code, LINE_LIMIT)).toBe(code);
  });

  it('leaves a bundle that does not parse unchanged, with a warning', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => undefined);
    const code = `${'a=1,'.repeat(LINE_LIMIT)}a=(`;

    expect(limitLineLength(code, LINE_LIMIT)).toBe(code);
    expect(warn).toHaveBeenCalledWith(expect.stringContaining('Could not parse the bundle'));
    warn.mockRestore();
  });

  it('breaks at the default line limit when none is given', () => {
    const limited = limitLineLength(makePackedBundle().repeat(DEFAULT_OBSIDIAN_PLUGIN_LINE_LIMIT / LINE_LIMIT));

    expect(Math.max(...limited.split('\n').map((line) => line.length))).toBeLessThan(DEFAULT_OBSIDIAN_PLUGIN_LINE_LIMIT * 2);
  });
});

describe('limitMainJsLineLength', () => {
  let folder = '';
  let mainJsPath = '';

  beforeEach(async () => {
    folder = await mkdtemp(join(tmpdir(), 'obsidian-plugin-line-limit-'));
    mainJsPath = join(folder, 'main.js');
  });

  afterEach(async () => {
    await rm(folder, { force: true, recursive: true });
  });

  it('rewrites a packed main.js of a production build', async () => {
    await writeFile(mainJsPath, makePackedBundle(), 'utf-8');

    await limitMainJsLineLength({ isProductionBuild: true, lineLimit: LINE_LIMIT, mainJsPath });

    const limitedCode = await readFile(mainJsPath, 'utf-8');
    expect(limitedCode.split('\n').length).toBeGreaterThan(1);
  });

  it('leaves main.js alone when the build is a development one or the limit is off', async () => {
    const code = makePackedBundle();
    await writeFile(mainJsPath, code, 'utf-8');

    await limitMainJsLineLength({ isProductionBuild: false, lineLimit: LINE_LIMIT, mainJsPath });
    await limitMainJsLineLength({ isProductionBuild: true, lineLimit: false, mainJsPath });

    expect(await readFile(mainJsPath, 'utf-8')).toBe(code);
  });

  it('does not rewrite a main.js that needs no change', async () => {
    await writeFile(mainJsPath, 'exports.a = 1;\n', 'utf-8');
    const { mtimeMs } = await stat(mainJsPath);

    await limitMainJsLineLength({ isProductionBuild: true, lineLimit: LINE_LIMIT, mainJsPath });

    const stats = await stat(mainJsPath);
    expect(stats.mtimeMs).toBe(mtimeMs);
  });

  it('does nothing when there is no main.js', async () => {
    await expect(limitMainJsLineLength({ isProductionBuild: true, lineLimit: LINE_LIMIT, mainJsPath })).resolves.toBeUndefined();
  });
});
